237	impl PromptResult {
238	    /// Get as string, suitable for interpolation.
239	    pub fn as_string(&self) -> String {
240	        match self {
241	            Self::Bool(b) => b.to_string(),
242	            Self::String(s) => s.clone(),
243	            Self::Strings(v) => v.join(","),
244	        }
245	    }
246	
247	    /// Get as bool if this is a Bool result.
248	    pub fn as_bool(&self) -> Option<bool> {
249	        match self {
250	            Self::Bool(b) => Some(*b),
251	            _ => None,
252	        }
253	    }
254	}
