1	//! Process group / job control regression tests.
2	//!
3	//! These tests verify that bivvy survives running under a real
4	//! job-controlling shell (zsh with `MONITOR` option). The existing PTY
5	//! tests spawn bivvy directly — the expectrl PTY *is* the controlling
6	//! terminal, so there's no parent shell doing process group management.
7	//! That topology can't surface the bug where zsh reclaims the foreground
8	//! group after a child process exits, causing SIGTTOU/SIGTTIN or
9	//! premature suspension.
10	//!
11	//! These tests spawn **zsh** inside the PTY, then run bivvy as a
12	//! command within that zsh session. This gives us:
13	//!   - Real job control (zsh's `MONITOR` option)
14	//!   - Real process group assignment and foreground management
15	//!   - Real signal delivery (SIGTTOU, SIGTTIN, SIGTSTP)
16	//!   - A parent shell that actively manages the terminal foreground
17	//!
18	//! The critical transition under test: after a child process (step
19	//! command) exits, bivvy must reclaim the terminal foreground to
20	//! render the next interactive prompt. If process group isolation or
21	//! foreground reclamation is broken, the prompt never appears and
22	//! the test times out — or zsh reports "suspended (tty output)".
23	#![cfg(unix)]
24	
25	use assert_cmd::cargo::cargo_bin;
26	use expectrl::Session;
27	use std::fs;
28	use std::process::Command;
29	use std::time::Duration;
30	use tempfile::TempDir;
31	
32	const TIMEOUT: Duration = Duration::from_secs(60);
33	
34	/// Marker printed by .zshrc to confirm the shell is ready.
35	const READY: &str = "ZSH_READY";
36	
37	// ── ANSI stripping ──────────────────────────────────────────────────
38	
39	/// Strip ANSI escape sequences from PTY output for readable snapshots.
40	///
41	/// Handles:
42	///   - CSI sequences: `ESC [ <params> <final>`
43	///   - OSC sequences: `ESC ] ... BEL` or `ESC ] ... ESC \`
44	///   - SS2/SS3:       `ESC N <char>` / `ESC O <char>`
45	///   - Two-byte:      `ESC <letter>` (e.g. `ESC =`, `ESC >`)
46	fn strip_ansi(s: &str) -> String {
47	    let mut result = String::with_capacity(s.len());
48	    let mut chars = s.chars().peekable();
49	
50	    while let Some(c) = chars.next() {
51	        if c == '\x1b' {
52	            match chars.peek() {
53	                // CSI: ESC [ <params> <final byte 0x40-0x7E>
54	                Some('[') => {
55	                    chars.next(); // consume '['
56	                    for ch in chars.by_ref() {
57	                        if ch.is_ascii() && (0x40..=0x7E).contains(&(ch as u8)) {
58	                            break;
59	                        }
60	                    }
61	                }
62	                // OSC: ESC ] ... (BEL | ESC \)
63	                Some(']') => {
64	                    chars.next(); // consume ']'
65	                    for ch in chars.by_ref() {
66	                        if ch == '\x07' {
67	                            break;
68	                        }
69	                        if ch == '\x1b' {
70	                            if chars.peek() == Some(&'\\') {
71	                                chars.next();
72	                            }
73	                            break;
74	                        }
75	                    }
76	                }
77	                // SS2 / SS3: ESC N/O + one character
78	                Some('N') | Some('O') => {
79	                    chars.next();
80	                    chars.next();
81	                }
82	                // Two-byte sequence: ESC + anything else
83	                Some(_) => {
84	                    chars.next();
85	                }
86	                None => {}
87	            }
88	        } else if c == '\x07' {
89	            // Bare BEL — skip
90	        } else {
91	            result.push(c);
92	        }
93	    }
94	    result
95	}
