97	/// Normalize PTY output for stable snapshots.
98	///
99	/// Only strips ANSI codes, removes \r, and replaces timing values
100	/// with `[TIME]`. Does NOT filter content — everything bivvy produces
101	/// should be visible in the snapshot.
102	fn normalize_for_snapshot(s: &str) -> String {
103	    let stripped = strip_ansi(s);
104	    let re_time = regex::Regex::new(r"\b\d+(\.\d+)?(ms|s)\b").unwrap();
105	    // Caret-notation escape sequences echoed by PTY: ^[[B, ^[[A, etc.
106	    let re_caret_csi = regex::Regex::new(r"\^\[[\[0-9;]*[A-Za-z~]").unwrap();
107	
108	    stripped
109	        .replace('\r', "")
110	        .lines()
111	        .map(|line| {
112	            let trimmed = line.trim_end();
113	            let no_caret = re_caret_csi.replace_all(trimmed, "");
114	            re_time.replace_all(&no_caret, "[TIME]").to_string()
115	        })
116	        // Drop leading zsh prompt noise (% prompt, $ prompt)
117	        .skip_while(|line| line.is_empty() || line.starts_with('%') || line.starts_with('$'))
118	        // Stop at trailing zsh prompt
119	        .take_while(|line| !line.starts_with('%'))
120	        .collect::<Vec<_>>()
121	        .join("\n")
122	}
