124	/// Assert that PTY output never contains "suspended" — the smoking gun
125	/// for the process group bug. Zsh prints "suspended (tty output)" or
126	/// "suspended (tty input)" when a background process tries terminal I/O.
127	fn assert_not_suspended(output: &str, context: &str) {
128	    let lower = strip_ansi(output).to_lowercase();
129	    assert!(
130	        !lower.contains("suspended"),
131	        "{context}: bivvy was suspended by zsh!\nOutput:\n{output}"
132	    );
133	}
