136	//
137	// Two safe abstractions over libc that contain all the `unsafe` for
138	// poll-based PTY interaction.
139	
140	/// Write bytes to a PTY session's master file descriptor.
141	fn pty_write(session: &Session, data: &[u8]) {
142	    use std::os::unix::io::AsRawFd;
143	    let fd = session.get_stream().as_raw_fd();
144	    // SAFETY: fd is a valid, open PTY master fd obtained from the Session.
145	    // data is a valid byte slice that outlives the call.  For the short
146	    // payloads used in interactive testing (single keys, escape sequences,
147	    // short lines), partial writes are not a concern.
148	    unsafe {
149	        libc::write(fd, data.as_ptr() as *const _, data.len());
150	    }
151	}
152	
153	/// Poll for available data on a PTY fd and drain it into `accumulated`.
154	///
155	/// Temporarily sets `O_NONBLOCK` to drain all buffered data without
156	/// blocking, then restores the original flags.  Returns `true` if the
157	/// poll indicated data was ready.
158	fn poll_and_drain(
159	    fd: std::os::unix::io::RawFd,
160	    accumulated: &mut String,
161	    poll_timeout_ms: i32,
162	) -> bool {
163	    // SAFETY: poll() with a single stack-allocated pollfd is a standard
164	    // POSIX syscall.  The pollfd is valid for the duration of the call.
165	    let ready = unsafe {
166	        let mut pfd = libc::pollfd {
167	            fd,
168	            events: libc::POLLIN,
169	            revents: 0,
170	        };
171	        libc::poll(&mut pfd, 1, poll_timeout_ms)
172	    };
173	
174	    if ready > 0 {
175	        let mut buf = [0u8; 4096];
176	        // SAFETY: fcntl F_GETFL/F_SETFL and read() are standard POSIX
177	        // calls on a valid PTY fd.  O_NONBLOCK is set temporarily to
178	        // drain all available data, then the original flags are restored.
179	        // The buffer is stack-allocated and valid for each read() call.
180	        unsafe {
181	            let flags = libc::fcntl(fd, libc::F_GETFL);
182	            libc::fcntl(fd, libc::F_SETFL, flags | libc::O_NONBLOCK);
183	            loop {
184	                let n = libc::read(fd, buf.as_mut_ptr() as *mut _, buf.len());
185	                if n <= 0 {
186	                    break;
187	                }
188	                let chunk = String::from_utf8_lossy(&buf[..n as usize]);
189	                accumulated.push_str(&chunk);
190	            }
191	            libc::fcntl(fd, libc::F_SETFL, flags & !libc::O_NONBLOCK);
192	        }
193	        true
194	    } else {
195	        false
196	    }
197	}
