201	/// Poll-based wait for a pattern in PTY output. Returns the full
202	/// accumulated output (ANSI-stripped) since this call started.
203	fn wait_for(session: &Session, pattern: &str, context: &str) -> String {
204	    use std::os::unix::io::AsRawFd;
205	    use std::time::Instant;
206	
207	    let fd = session.get_stream().as_raw_fd();
208	    let mut accumulated = String::new();
209	    let start = Instant::now();
210	
211	    loop {
212	        if start.elapsed() > TIMEOUT {
213	            let clean = strip_ansi(&accumulated);
214	            panic!(
215	                "{context}\n\
216	                 Expected: {pattern:?}\n\
217	                 Timed out after {TIMEOUT:?}\n\
218	                 Accumulated PTY output (ANSI stripped):\n\
219	                 ---\n{clean}\n---"
220	            );
221	        }
222	
223	        poll_and_drain(fd, &mut accumulated, 200);
224	
225	        if strip_ansi(&accumulated).contains(pattern) {
226	            return strip_ansi(&accumulated);
227	        }
228	    }
229	}
