231	/// Wait for a pattern, then send a single key. Returns accumulated output.
232	#[allow(dead_code)]
233	fn wait_and_send(session: &Session, pattern: &str, key: u8, context: &str) -> String {
234	    let output = wait_for(session, pattern, context);
235	    send_key(session, key);
236	    output
237	}
