564	/// A failing step under zsh job control. Step 1 auto-runs,
565	/// step 2 fails and shows the recovery menu. We navigate to "Abort"
566	/// via arrow keys and Enter.
567	#[test]
568	#[ignore = "PTY/zsh environment sensitive: arrow-key navigation and snapshot drift across hosts"]
569	fn failed_step_under_zsh_job_control() {
570	    let temp = setup_project(FAILING_CONFIG);
571	    let session = spawn_zsh(temp.path());
572	
573	    wait_for(&session, READY, "Waiting for zsh to start");
574	    send_line(&session, "$BIVVY run");
575	
576	    // Step 1: auto-runs (no prompt). Step 2: auto-runs, fails.
577	    // Recovery menu: Retry / Skip / Shell / Abort.
578	    // Navigate to Abort: 3x arrow-down, then Enter.
579	    //
580	    // TERM=dumb routes through prompt_select_dumb (bypasses dialoguer
581	    // entirely). Options are printed once with no redraw cycle. Arrow
582	    // keys are parsed by console::Term::read_key() in raw mode — ANSI
583	    // escape parsing is hardcoded, not terminfo-dependent, so arrow
584	    // navigation works regardless of TERM value. Internal selection
585	    // state updates silently (no visual feedback on dumb terminals).
586	    //
587	    // Wait for the last option ("Abort") to confirm all options rendered
588	    // and raw mode is active before sending arrow keys.
589	    wait_for(&session, "Abort", "Recovery menu options");
590	    for _ in 0..3 {
591	        send_bytes(&session, ARROW_DOWN);
592	    }
593	    send_key(&session, KEY_ENTER);
594	
595	    // Wait for the closing box line to ensure full summary is captured
596	    let summary = wait_for(
597	        &session,
598	        "\u{2514}\u{2500}\u{2500}\u{2500}", // └───
599	        "Workflow summary after abort",
600	    );
601	    assert_not_suspended(&summary, "failed step workflow");
602	    insta::assert_snapshot!(
603	        "failed_step_workflow_summary",
604	        normalize_for_snapshot(&summary)
605	    );
606	
607	    assert_zsh_exit_code(&session, 1, "failing workflow");
608	
609	    assert!(
610	        temp.path().join(".succeeded.txt").exists(),
611	        "Step 1 should have run"
612	    );
613	    assert!(
614	        !temp.path().join(".after-fail.txt").exists(),
615	        "Step 3 should NOT have run (blocked)"
616	    );
617	
618	    // Zsh must still be responsive after bivvy failure
619	    let nonce = std::time::SystemTime::now()
620	        .duration_since(std::time::UNIX_EPOCH)
621	        .unwrap()
622	        .as_nanos();
623	    let alive_tag = format!("ALIVE_{nonce}");
624	    send_line(&session, &format!("printf '{alive_tag}\\n'"));
625	    wait_for(&session, &alive_tag, "Zsh responsive after failure");
