52	/// Returns true when `TERM=dumb`.
53	///
54	/// Dumb terminals don't support cursor movement, so interactive redraws
55	/// (clear-and-repaint cycles) produce garbage output. When true, prompts
56	/// render forward-only and `clear_lines` becomes a no-op.
57	pub(crate) fn is_dumb_term() -> bool {
58	    std::env::var("TERM").map(|v| v == "dumb").unwrap_or(false)
59	}
60	
61	use crate::error::Result;
62	use indicatif::ProgressBar;
63	
64	/// Output methods for displaying messages, warnings, errors, and hints.
65	pub trait OutputWriter {
66	    /// Display a message to the user.
67	    fn message(&mut self, msg: &str);
68	
69	    /// Display a success message.
70	    fn success(&mut self, msg: &str);
71	
72	    /// Display a warning message.
73	    fn warning(&mut self, msg: &str);
74	
75	    /// Display an error message.
76	    fn error(&mut self, msg: &str);
77	
78	    /// Show a contextual hint to the user.
79	    fn show_hint(&mut self, hint: &str) {
80	        self.message(hint);
81	    }
82	
83	    /// Show a bordered error block with command, output, and optional hint.
84	    ///
85	    /// `indent` is the column at which the block should align (typically the
86	    /// step number width, so error content lines up under the step name).
87	    /// Implementations that don't render a visual box may ignore it.
88	    fn show_error_block(&mut self, command: &str, output: &str, hint: Option<&str>, indent: usize) {
89	        let _ = indent;
90	        self.error(command);
91	        if !output.is_empty() {
92	            self.message(output);
93	        }
94	        if let Some(h) = hint {
95	            self.show_hint(h);
96	        }
97	    }
98	}
99	
100	/// Interactive prompting.
101	pub trait Prompter {
102	    /// Show a prompt and get user input.
103	    fn prompt(&mut self, prompt: &Prompt) -> Result<PromptResult>;
104	}
105	
106	/// Spinner creation and management.
107	pub trait SpinnerFactory {
108	    /// Start a spinner for an operation.
109	    fn start_spinner(&mut self, message: &str) -> Box<dyn SpinnerHandle>;
110	
111	    /// Start a spinner with leading indentation.
112	    fn start_spinner_indented(&mut self, message: &str, indent: usize) -> Box<dyn SpinnerHandle> {
113	        let _ = indent;
114	        self.start_spinner(message)
115	    }
116	}
117	
118	/// Headers and progress indicators.
119	pub trait ProgressDisplay {
120	    /// Show a header/banner.
121	    fn show_header(&mut self, title: &str);
122	
123	    /// Show progress (e.g., "Step 3 of 7").
124	    fn show_progress(&mut self, current: usize, total: usize);
125	}
126	
127	/// Output mode and interactivity state.
128	pub trait UiState {
129	    /// Get the current output mode.
130	    fn output_mode(&self) -> OutputMode;
131	
132	    /// Check if running in interactive mode.
133	    fn is_interactive(&self) -> bool;
134	
135	    /// Change the output mode at runtime.
136	    fn set_output_mode(&mut self, mode: OutputMode);
137	
138	    /// Attach a [`crate::ui::surface::TerminalSurface`] for the
139	    /// duration of a run. Default impl is a no-op for UIs that have no
140	    /// surface concept (mock, non-interactive). Only `TerminalUI`
141	    /// overrides this.
142	    fn attach_surface(&mut self, _surface: std::sync::Arc<crate::ui::surface::TerminalSurface>) {}
143	
144	    /// Detach the surface attached by [`Self::attach_surface`].
145	    fn detach_surface(&mut self) {}
146	}
147	
148	/// Combined trait for all generic user interface interactions.
149	///
150	/// Run-path workflow chrome and per-step rendering are *not* part of
151	/// this trait — see [`crate::runner::display`] for those concerns. This
152	/// trait is intentionally narrow so that init / status / list / lint
153	/// commands can mock it without dragging in workflow types.
154	pub trait UserInterface:
155	    OutputWriter + Prompter + SpinnerFactory + ProgressDisplay + UiState
156	{
157	}
158	
159	impl<T> UserInterface for T where
160	    T: OutputWriter + Prompter + SpinnerFactory + ProgressDisplay + UiState
161	{
162	}
163	
164	/// Handle for controlling a spinner.
165	pub trait SpinnerHandle {
166	    /// Update the spinner message.
167	    fn set_message(&mut self, msg: &str);
168	
169	    /// Mark the operation as successful.
170	    fn finish_success(&mut self, msg: &str);
171	
172	    /// Mark the operation as failed.
173	    fn finish_error(&mut self, msg: &str);
174	
175	    /// Mark as skipped.
176	    fn finish_skipped(&mut self, msg: &str);
177	
178	    /// Clear the spinner without leaving any output.
179	    fn finish_and_clear(&mut self);
180	
181	    /// Get a clone of the underlying progress bar, if available.
182	    ///
183	    /// This is used for live output streaming: the cloned bar can be shared
184	    /// with an `OutputCallback` to update the spinner message in real-time.
185	    /// Returns `None` for mock/hidden spinners.
186	    fn progress_bar(&self) -> Option<ProgressBar> {
187	        None
188	    }
189	}
190	
191	/// A prompt to show to the user.
192	#[derive(Debug, Clone)]
193	pub struct Prompt {
194	    /// Unique key for the prompt (used for caching/lookup).
195	    pub key: String,
196	    /// The question to display.
197	    pub question: String,
198	    /// The type of prompt.
199	    pub prompt_type: PromptType,
200	    /// Default value if user just presses enter.
201	    pub default: Option<String>,
202	}
203	
204	/// The type of prompt.
205	#[derive(Debug, Clone)]
206	pub enum PromptType {
207	    /// Yes/no confirmation.
208	    Confirm,
209	    /// Free-form text input.
210	    Input,
211	    /// Select one from a list of options.
212	    Select { options: Vec<PromptOption> },
213	    /// Select multiple from a list of options.
214	    MultiSelect { options: Vec<PromptOption> },
215	}
216	
217	/// An option in a select prompt.
218	#[derive(Debug, Clone)]
219	pub struct PromptOption {
220	    /// Display label.
221	    pub label: String,
222	    /// Value returned when selected.
223	    pub value: String,
224	}
225	
226	/// Result of a prompt.
227	#[derive(Debug, Clone)]
228	pub enum PromptResult {
229	    /// Boolean result from confirm.
230	    Bool(bool),
231	    /// String result from input or select.
232	    String(String),
233	    /// Multiple string results from multi-select.
234	    Strings(Vec<String>),
235	}
236	
237	impl PromptResult {
238	    /// Get as string, suitable for interpolation.
239	    pub fn as_string(&self) -> String {
240	        match self {
241	            Self::Bool(b) => b.to_string(),
242	            Self::String(s) => s.clone(),
243	            Self::Strings(v) => v.join(","),
244	        }
245	    }
246	
247	    /// Get as bool if this is a Bool result.
248	    pub fn as_bool(&self) -> Option<bool> {
249	        match self {
250	            Self::Bool(b) => Some(*b),
251	            _ => None,
252	        }
253	    }
254	}
