1	//! Interactive recovery for step failures.
2	//!
3	//! When a step fails during `bivvy run`, this module provides a recovery menu
4	//! allowing the user to retry, fix, skip, open a debug shell, enter a custom
5	//! fix command, or abort.
6	
7	use std::collections::{HashMap, HashSet};
8	use std::path::Path;
9	
10	use crate::error::Result;
11	use crate::shell::{execute_streaming, CommandOptions, OutputCallback};
12	use crate::ui::{FixOutputSink, OutputWriter, Prompt, PromptOption, PromptType, Prompter};
13	
14	use super::diagnostic::ResolutionCandidate;
15	use super::patterns::FixSuggestion;
16	
17	/// Recovery action chosen by the user.
18	#[derive(Debug, Clone, PartialEq, Eq)]
19	pub enum RecoveryAction {
20	    /// Re-execute the step.
21	    Retry,
22	    /// Run the suggested fix command, then re-execute.
23	    Fix(String),
24	    /// Run a user-entered custom fix command, then re-execute.
25	    CustomFix(String),
26	    /// Skip this step and continue.
27	    Skip,
28	    /// Open a debug shell, then return to the recovery menu.
29	    Shell,
30	    /// Stop the workflow.
31	    Abort,
32	}
33	
34	/// Prompt the user for a recovery action after a step failure.
35	///
36	/// Returns the chosen action. The `fix` parameter controls whether a Fix
37	/// option appears in the menu. The `has_hint` flag indicates a low-confidence
38	/// match exists, which adds a "Fix (custom)" option for the user to enter
39	/// their own command. The `fix_history` set tracks which fix commands have
40	/// already been attempted — if the suggested fix was already tried, it is
41	/// not offered again.
42	pub fn prompt_recovery(
43	    ui: &mut (impl Prompter + OutputWriter + ?Sized),
44	    step_name: &str,
45	    fix: Option<&FixSuggestion>,
46	    has_hint: bool,
47	    fix_history: &HashSet<String>,
48	    step_indent: usize,
49	) -> Result<RecoveryAction> {
50	    let pad = " ".repeat(step_indent);
51	    let mut options = vec![PromptOption {
52	        label: "Retry".to_string(),
53	        value: "retry".to_string(),
54	    }];
55	
56	    if let Some(f) = fix {
57	        if fix_history.contains(&f.command) {
58	            ui.warning(&format!(
59	                "{}Previous fix `{}` did not resolve this error.",
60	                pad, f.command
61	            ));
62	        } else {
63	            options.push(PromptOption {
64	                label: format!("Fix — {}", f.label),
65	                value: "fix".to_string(),
66	            });
67	        }
68	    }
69	
70	    if has_hint {
71	        options.push(PromptOption {
72	            label: "Fix (custom) — enter your own command".to_string(),
73	            value: "custom_fix".to_string(),
74	        });
75	    }
76	
77	    options.push(PromptOption {
78	        label: "Skip".to_string(),
79	        value: "skip".to_string(),
80	    });
81	
82	    options.push(PromptOption {
83	        label: "Shell".to_string(),
84	        value: "shell".to_string(),
85	    });
86	
87	    options.push(PromptOption {
88	        label: "Abort".to_string(),
89	        value: "abort".to_string(),
90	    });
91	
92	    let prompt = Prompt {
93	        key: format!("recovery_{}", step_name),
94	        question: "How do you want to proceed?".to_string(),
95	        prompt_type: PromptType::Select { options },
96	        default: Some("retry".to_string()),
97	    };
98	
99	    let answer = ui.prompt(&prompt)?;
100	    let value = answer.as_string();
101	
102	    match value.as_str() {
103	        "retry" => Ok(RecoveryAction::Retry),
104	        "fix" => {
105	            if let Some(f) = fix {
106	                Ok(RecoveryAction::Fix(f.command.clone()))
107	            } else {
108	                Ok(RecoveryAction::Retry)
109	            }
110	        }
111	        "custom_fix" => {
112	            let input_prompt = Prompt {
113	                key: format!("custom_fix_{}", step_name),
114	                question: "Enter fix command:".to_string(),
115	                prompt_type: PromptType::Input,
116	                default: None,
117	            };
118	            let input = ui.prompt(&input_prompt)?;
119	            let cmd = input.as_string();
120	            if cmd.trim().is_empty() {
121	                // User entered nothing, treat as retry
122	                Ok(RecoveryAction::Retry)
123	            } else {
124	                Ok(RecoveryAction::CustomFix(cmd))
125	            }
126	        }
127	        "skip" => Ok(RecoveryAction::Skip),
128	        "shell" => Ok(RecoveryAction::Shell),
129	        "abort" => Ok(RecoveryAction::Abort),
130	        _ => Ok(RecoveryAction::Retry),
131	    }
132	}
133	
134	/// Prompt the user for a recovery action using ranked diagnostic resolutions.
135	///
136	/// Shows up to 3 high-confidence fixes (>= 0.6) and up to 2 suggestions
137	/// (0.3–0.59). Resolutions already in `fix_history` are demoted with a
138	/// warning instead of being offered again.
139	pub fn prompt_recovery_multi(
140	    ui: &mut (impl Prompter + OutputWriter + ?Sized),
141	    step_name: &str,
142	    resolutions: &[ResolutionCandidate],
143	    fix_history: &HashSet<String>,
144	    step_indent: usize,
145	) -> Result<RecoveryAction> {
146	    let pad = " ".repeat(step_indent);
147	    let mut options = vec![PromptOption {
148	        label: "Retry".to_string(),
149	        value: "retry".to_string(),
150	    }];
151	
152	    // Collect actionable resolutions (with runnable commands)
153	    let mut fix_count = 0;
154	    let mut suggestion_count = 0;
155	    let mut fix_commands: Vec<String> = Vec::new();
156	
157	    for resolution in resolutions {
158	        let cmd = match &resolution.command {
159	            Some(c) => c,
160	            None => continue,
161	        };
162	
163	        if fix_history.contains(cmd) {
164	            ui.warning(&format!(
165	                "{}Previous fix `{}` did not resolve this error.",
166	                pad, cmd
167	            ));
168	            continue;
169	        }
170	
171	        if resolution.confidence >= 0.6 && fix_count < 3 {
172	            options.push(PromptOption {
173	                label: format!("Fix — {}", resolution.label),
174	                value: format!("fix_{}", fix_count),
175	            });
176	            fix_commands.push(cmd.clone());
177	            fix_count += 1;
178	        } else if resolution.confidence >= 0.3 && suggestion_count < 2 {
179	            options.push(PromptOption {
180	                label: format!("Suggestion — {}", resolution.label),
181	                value: format!("fix_{}", fix_commands.len()),
182	            });
183	            fix_commands.push(cmd.clone());
184	            suggestion_count += 1;
185	        }
186	    }
187	
188	    // Custom fix is available when any resolution exists
189	    let has_any = !resolutions.is_empty();
190	    if has_any {
191	        options.push(PromptOption {
192	            label: "Fix (custom) — enter your own command".to_string(),
193	            value: "custom_fix".to_string(),
194	        });
195	    }
196	
197	    options.push(PromptOption {
198	        label: "Skip".to_string(),
199	        value: "skip".to_string(),
200	    });
201	    options.push(PromptOption {
202	        label: "Shell".to_string(),
203	        value: "shell".to_string(),
204	    });
205	    options.push(PromptOption {
206	        label: "Abort".to_string(),
207	        value: "abort".to_string(),
208	    });
209	
210	    let prompt = Prompt {
211	        key: format!("recovery_{}", step_name),
212	        question: "How do you want to proceed?".to_string(),
213	        prompt_type: PromptType::Select { options },
214	        default: Some("retry".to_string()),
215	    };
216	
217	    let answer = ui.prompt(&prompt)?;
218	    let value = answer.as_string();
219	
220	    match value.as_str() {
221	        "retry" => Ok(RecoveryAction::Retry),
222	        "custom_fix" => {
223	            let input_prompt = Prompt {
224	                key: format!("custom_fix_{}", step_name),
225	                question: "Enter fix command:".to_string(),
226	                prompt_type: PromptType::Input,
227	                default: None,
228	            };
229	            let input = ui.prompt(&input_prompt)?;
230	            let cmd = input.as_string();
231	            if cmd.trim().is_empty() {
232	                Ok(RecoveryAction::Retry)
233	            } else {
234	                Ok(RecoveryAction::CustomFix(cmd))
235	            }
236	        }
237	        "skip" => Ok(RecoveryAction::Skip),
238	        "shell" => Ok(RecoveryAction::Shell),
239	        "abort" => Ok(RecoveryAction::Abort),
240	        other => {
241	            // Parse "fix_N" to get the command
242	            if let Some(idx_str) = other.strip_prefix("fix_") {
243	                if let Ok(idx) = idx_str.parse::<usize>() {
244	                    if let Some(cmd) = fix_commands.get(idx) {
245	                        return Ok(RecoveryAction::Fix(cmd.clone()));
246	                    }
247	                }
248	            }
249	            Ok(RecoveryAction::Retry)
250	        }
251	    }
252	}
