697	                        &self.step.name,
698	                        CheckResult::passed(eval_result.reason.clone()),
699	                    ),
700	                    SkipCategory::Satisfied,
701	                )));
702	            }
703	            // User chose yes — fall through to execution
704	        } else if prompt_key.starts_with("autorun_") {
705	            let prompt_text = format!("Run {}?", self.step.title);
706	            let prompt = Prompt {
