823	                    SkipCategory::UserDeclined,
824	                )));
825	            }
826	            // clear_lines removed — surface tracks regions
827	        } else if prompt_key.starts_with("sensitive_") {
828	            let prompt_text = "Handles sensitive data. Continue?";
829	            let prompt = Prompt {
830	                key: prompt_key.to_string(),
831	                question: prompt_text.to_string(),
832	                prompt_type: PromptType::Select {
833	                    options: vec![
834	                        PromptOption {
835	                            label: "Yes (y)".to_string(),
836	                            value: "yes".to_string(),
837	                        },
838	                        PromptOption {
839	                            label: "No (n)".to_string(),
840	                            value: "no".to_string(),
841	                        },
842	                    ],
843	                },
844	                default: Some("yes".to_string()),
845	            };
846	            event_bus.emit(&BivvyEvent::UserPrompted {
847	                step: Some(self.step_name.to_string()),
848	                prompt: prompt_text.to_string(),
849	                options: vec!["Yes (y)".to_string(), "No (n)".to_string()],
850	            });
851	            let answer = ui.prompt(&prompt)?;
852	            let answer_str = answer.as_string();
853	            event_bus.emit(&BivvyEvent::UserResponded {
854	                step: Some(self.step_name.to_string()),
855	                input: answer_str.clone(),
856	                method: crate::logging::InputMethod::ArrowSelect,
857	            });
858	            if answer_str != "yes" {
859	                if self.step.behavior.skippable {
860	                    event_bus.emit(&BivvyEvent::StepSkipped {
