992	
993	        // [10/15] = 7 chars + space = 8
994	        let mgr = StepManager::new(&step, "setup", 9, 15, &theme);
995	        assert_eq!(mgr.step_number(), "[10/15]");
996	        assert_eq!(mgr.step_indent(), 8);
997	        assert_eq!(mgr.step_pad(), "        ");
998	
999	        // [1/1] = 5 chars + space = 6
1000	        let mgr = StepManager::new(&step, "setup", 0, 1, &theme);
1001	        assert_eq!(mgr.step_number(), "[1/1]");
1002	        assert_eq!(mgr.step_indent(), 6);
1003	
1004	        // [100/100] = 9 chars + space = 10
1005	        let mgr = StepManager::new(&step, "setup", 99, 100, &theme);
1006	        assert_eq!(mgr.step_number(), "[100/100]");
1007	        assert_eq!(mgr.step_indent(), 10);
1008	    }
1009	}
