        store.append(&resolved).unwrap();
        store.append(&FeedbackEntry::new("open issue")).unwrap();

        // List only resolved
        let result =
            list_feedback(&store, Some("resolved".to_string()), None, false, &mut ui).unwrap();

        assert_eq!(result, 0);
    }

