fn map_dialoguer_err(e: dialoguer::Error) -> BivvyError {
    BivvyError::Io(e.into())
}

/// Returns true if the key is Ctrl+D (EOF signal in terminals).
fn is_eof_key(key: &Key) -> bool {
    matches!(key, Key::Char('\x04'))
}

/// Creates an IO error representing EOF from Ctrl+D.
fn eof_error() -> std::io::Error {
    std::io::Error::new(std::io::ErrorKind::UnexpectedEof, "Ctrl+D pressed")
}

/// Dialoguer theme without the default yellow `?` prefix.

